import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"出租车司机求职邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/10-taxi-driver-job-application.md","filePath":"zh/more/maltese/practice/emails/10-taxi-driver-job-application.md"}'),e={name:"zh/more/maltese/practice/emails/10-taxi-driver-job-application.md"},o=r('<h1 id="出租车司机求职邮件" tabindex="-1">出租车司机求职邮件 <a class="header-anchor" href="#出租车司机求职邮件" aria-label="Permalink to &quot;出租车司机求职邮件&quot;">​</a></h1><p><strong>场景：</strong> 申请人写信给出租车公司，申请出租车司机职位。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:info@taksis.com" target="_blank" rel="noreferrer">info@taksis.com</a><strong>Mingħand（发件人 From）：</strong> [isem]@email.com <strong>Data（日期）：</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Applikazzjoni ta&#39; xogħol ta&#39; sewwieq tat-taksi</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@taksis.com" target="_blank" rel="noreferrer">info@taksis.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; sewwieq tat-taksi</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; sewwieq tat-taksi.</p><p>Għandi liċenzja tas-sewqan u liċenzja speċjali tat-taksi.</p><p>Naf it-toroq ta&#39; Malta u ta&#39; Għawdex tajjeb ħafna.</p><p>Jiena sewwieq sigur, onest u responsabbli.</p><p>Nittratta lill-klijenti b&#39;rispett u bil-ħlewwa.</p><p>Nista&#39; naħdem billejl u fi tmiem il-ġimgħa.</p><p>Nżomm il-karozza nadifa u komda għall-klijenti.</p><p>Nispera li nisma&#39; mingħandkom dalwaqt.</p><p>Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@taksis.com" target="_blank" rel="noreferrer">info@taksis.com</a></p><p><strong>整句：</strong> 收件人（To）：info@taksis.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:info@taksis.com" target="_blank" rel="noreferrer">info@taksis.com</a></td><td>邮箱地址</td><td>出租车公司的招聘邮箱（示例）</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>整句：</strong> 发件人（From）：[你的名字]@email.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td>[isem]@email.com</td><td>邮箱地址</td><td>你的邮箱占位，请替换为真实邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 15 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>15</td><td>十五</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; sewwieq tat-taksi</p><p><strong>整句：</strong> 主题：出租车司机职位申请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Applikazzjoni</td><td>申请</td><td>阴性名词，借词 application</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>xogħol</td><td>工作；职位</td><td>阳性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>sewwieq</td><td>司机</td><td>阳性名词</td></tr><tr><td>tat-taksi</td><td>出租车的</td><td><code>ta&#39;</code> + <code>it-taksi</code> 缩合</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>整句：</strong> 亲爱的先生 / 女士：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiż</td><td>亲爱的</td><td>阳性单数形式</td></tr><tr><td>Sinjur</td><td>先生</td><td>阳性名词</td></tr><tr><td>/</td><td>或</td><td>表示二选一</td></tr><tr><td>Sinjura</td><td>女士</td><td>阴性名词</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; sewwieq tat-taksi.</p><p><strong>整句：</strong> 我写信是为了申请出租车司机职位。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Qed</td><td>正在（进行时标记）</td><td>与动词连用表示正在做某事</td></tr><tr><td>nikteb</td><td>我写</td><td>第一人称单数现在时</td></tr><tr><td>biex</td><td>为了</td><td>引出目的状语</td></tr><tr><td>napplika</td><td>我申请</td><td>第一人称单数形式，借词 apply</td></tr><tr><td>għall-impjieg</td><td>申请职位</td><td><code>għal</code> + <code>l-impjieg</code> 缩合</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>sewwieq</td><td>司机</td><td>阳性名词</td></tr><tr><td>tat-taksi</td><td>出租车的</td><td><code>ta&#39;</code> + <code>it-taksi</code> 缩合</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi liċenzja tas-sewqan u liċenzja speċjali tat-taksi.</p><p><strong>整句：</strong> 我持有驾驶执照和出租车专用执照。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandi</td><td>我有</td><td><code>għand</code> 的第一人称单数形式</td></tr><tr><td>liċenzja</td><td>执照</td><td>阴性名词，借词 licence</td></tr><tr><td>tas-sewqan</td><td>驾驶的</td><td><code>ta&#39;</code> + <code>is-sewqan</code> 缩合</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>liċenzja</td><td>执照</td><td>阴性名词</td></tr><tr><td>speċjali</td><td>专门的；特殊的</td><td>形容词，借词 special</td></tr><tr><td>tat-taksi</td><td>出租车的</td><td><code>ta&#39;</code> + <code>it-taksi</code> 缩合</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Naf it-toroq ta&#39; Malta u ta&#39; Għawdex tajjeb ħafna.</p><p><strong>整句：</strong> 我对马耳他和戈佐岛的道路非常熟悉。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Naf</td><td>我知道；我熟悉</td><td>第一人称单数形式</td></tr><tr><td>it-toroq</td><td>道路</td><td><code>triq</code> 的复数形式，带定冠词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>Malta</td><td>马耳他</td><td>地名</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>Għawdex</td><td>戈佐岛</td><td>马耳他第二大岛的地名</td></tr><tr><td>tajjeb</td><td>好</td><td>此处作副词“很好地”</td></tr><tr><td>ħafna</td><td>非常</td><td>程度副词</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Jiena sewwieq sigur, onest u responsabbli.</p><p><strong>整句：</strong> 我是一个安全、诚实且负责任的司机。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jiena</td><td>我</td><td>第一人称单数代词（<code>Jien</code> 的变体）</td></tr><tr><td>sewwieq</td><td>司机</td><td>阳性名词</td></tr><tr><td>sigur</td><td>安全的</td><td>形容词</td></tr><tr><td>onest</td><td>诚实的</td><td>形容词，借词 honest</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>responsabbli</td><td>负责任的</td><td>形容词，借词 responsible</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Nittratta lill-klijenti b&#39;rispett u bil-ħlewwa.</p><p><strong>整句：</strong> 我尊重而亲切地对待顾客。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nittratta</td><td>我对待</td><td>第一人称单数形式，借词 treat</td></tr><tr><td>lill-klijenti</td><td>对顾客们</td><td><code>li</code> + <code>l-klijenti</code> 缩合</td></tr><tr><td>b&#39;rispett</td><td>带着尊重</td><td><code>b&#39;</code>“以” + <code>rispett</code>“尊重”</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>bil-ħlewwa</td><td>亲切地</td><td><code>b&#39;</code> + <code>il-ħlewwa</code>“亲切/温柔”缩合</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; naħdem billejl u fi tmiem il-ġimgħa.</p><p><strong>整句：</strong> 我可以上夜班，也可以在周末工作。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我能</td><td>第一人称单数形式</td></tr><tr><td>naħdem</td><td>我工作</td><td>第一人称单数现在时</td></tr><tr><td>billejl</td><td>在夜间</td><td><code>bil-lejl</code>“在晚上”的缩合形式</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>fi</td><td>在……里</td><td>介词 <code>f&#39;</code> 的变体</td></tr><tr><td>tmiem</td><td>结束；末尾</td><td><code>tmiem il-ġimgħa</code> 固定表达“周末”</td></tr><tr><td>il-ġimgħa</td><td>星期</td><td>阴性名词，带定冠词</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nżomm il-karozza nadifa u komda għall-klijenti.</p><p><strong>整句：</strong> 我保持车子干净舒适，让顾客满意。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nżomm</td><td>我保持</td><td>第一人称单数形式</td></tr><tr><td>il-karozza</td><td>汽车</td><td>阴性名词，带定冠词</td></tr><tr><td>nadifa</td><td>干净的</td><td>阴性单数形容词，与 <code>karozza</code> 一致</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>komda</td><td>舒适的</td><td>阴性单数形容词，与 <code>karozza</code> 一致</td></tr><tr><td>għall-klijenti</td><td>为了顾客们</td><td><code>għal</code> + <code>il-klijenti</code> 缩合</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li nisma&#39; mingħandkom dalwaqt.</p><p><strong>整句：</strong> 我希望很快收到你们的回复。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数形式</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>nisma&#39;</td><td>我听到；收到消息</td><td>第一人称单数形式</td></tr><tr><td>mingħandkom</td><td>从你们那里</td><td><code>mingħand</code> + <code>-kom</code>“你们”</td></tr><tr><td>dalwaqt</td><td>很快</td><td>副词</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p><strong>整句：</strong> 感谢你们考虑我的申请。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>talli</td><td>因为（你们）……</td><td>引出原因的书面表达</td></tr><tr><td>qiesu</td><td>他们考虑了</td><td><code>qies</code> 的第三人称复数过去时</td></tr><tr><td>l-applikazzjoni</td><td>申请</td><td>阴性名词，带定冠词</td></tr><tr><td>tiegħi</td><td>我的</td><td>所有格代词</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>整句：</strong> 此致敬意，[你的名字]（正式邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Ismek</td><td>你的名字</td><td><code>isem</code>“名字” + <code>-ek</code>“你的”；请替换为真实姓名</td></tr></tbody></table>',61),i=[o];function l(n,s,h,p,c,b){return d(),a("div",null,i)}const u=t(e,[["render",l]]);export{m as __pageData,u as default};
